<?php
namespace App\Core; final class Router{private array $routes=[]; public function get($p,$a){$this->add('GET',$p,$a);} public function post($p,$a){$this->add('POST',$p,$a);} public function add($m,$p,$a){$this->routes[]=[$m,'#^'.preg_replace('#\{([a-z_]+)\}#','(?P<$1>[^/]+)',$p).'$#',$a];} public function dispatch($method,$uri):void{$path=parse_url($uri,PHP_URL_PATH) ?: '/'; foreach($this->routes as [$m,$rx,$a]){if($m===$method && preg_match($rx,$path,$mat)){[$c,$fn]=$a;$params=array_filter($mat,'is_string',ARRAY_FILTER_USE_KEY);(new $c)->$fn(...array_values($params));return;}} http_response_code(404); echo 'صفحه یافت نشد';}}
